import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.B7pF4b99.js";const k=JSON.parse('{"title":"Thread 階段 B/C：多 Thread 核心與共享生命週期","description":"","frontmatter":{},"headers":[],"relativePath":"thread-stage-b.md","filePath":"thread-stage-b.md","lastUpdated":1794297816000}'),r={name:"thread-stage-b.md"};function l(d,e,n,o,h,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="thread-階段-b-c-多-thread-核心與共享生命週期" tabindex="-1">Thread 階段 B/C：多 Thread 核心與共享生命週期 <a class="header-anchor" href="#thread-階段-b-c-多-thread-核心與共享生命週期" aria-label="Permalink to &quot;Thread 階段 B/C：多 Thread 核心與共享生命週期&quot;">​</a></h1><p>2026-11-10：在階段 A 的 TCB 排程基礎上，接入同一 Process 的多條 user Thread、額外 user stacks、create/join/exit/gettid，以及共享資源安全清理。</p><h2 id="實作範圍" tabindex="-1">實作範圍 <a class="header-anchor" href="#實作範圍" aria-label="Permalink to &quot;實作範圍&quot;">​</a></h2><ul><li>每 Process 最多 8 個占用 TCB slots、全系統仍最多 32 個 TCB。NEW、Ready、Running、Waiting 與未 join 的 Zombie 都占槽；TID 單調遞增。</li><li><code>SYS_THREAD_CREATE=42</code>、<code>JOIN=43</code>、<code>EXIT=44</code>、<code>GETTID=45</code> 已接入核心及 <code>user/lib/api.h</code>。Thread return 會經 <code>user/lib/thread.S</code> trampoline 轉成 Thread exit。</li><li>每個額外 Thread 使用 32 KiB RW stack、1 頁未映射 guard、16 KiB guarded kernel stack。VM page metadata、demand fault、FIFO/swap、clone、destroy、usage 都納入額外 stack；stack slot 在發布 Ready 前保留並預載最上方一頁。</li><li>Join 使用 TID claim、cycle scan、狀態 copyout 與額外 stack 回收；只有 scheduler 確認所有 Process Thread 已離開 kernel stack 後才做群組資源清理。Process exit、kill 與未處理 user fault 都會取消同 Process 其他 Thread。</li><li>Fork/exec 檢查所有占用 TCB slots；只允許唯一 Thread。Fork 複製目前額外 user stack 的 reservation/內容，exec 回到主 stack。<code>image_changing</code> 阻止同時建立 Thread。</li><li>Read/write 在 syscall 開始固定 FD 對應的 OFD 並持有短期引用，阻塞時不會因 close/reuse 而改操作新 FD。FD open/pipe 使用保留標記，pipe descriptor 僅在 copyout 後發布。FD table 修改使用單 hart syscall 下的短 SIE=0 原子區段，不跨等待持有 table lock。</li><li>相對路徑在 syscall 入口複製 cwd；同一個 FS copy 的 source/destination 共用同一快照。Child wait 使用單一 TID claim；取消與 copyout 失敗保留可重試結果。TTY raw owner 使用呼叫者 TID。</li><li>workstate 將已回收 Thread 的 ticks 留在 Process aggregate，並將同一 VmSpace RSS 計算一次。群組清理完成後 Zombie Process 不再保有 TCB；<code>ps</code> 顯示 TID 0，<code>pcb</code> 說明沒有占用 Thread slots。</li></ul><h2 id="簡化與尚未完成" tabindex="-1">簡化與尚未完成 <a class="header-anchor" href="#簡化與尚未完成" aria-label="Permalink to &quot;簡化與尚未完成&quot;">​</a></h2><p>單 hart 下以短、不可切換的 descriptor table 操作、FD reservation 與 OFD pins 保護共享 FD table，沒有再引入第二把 table gate。未增加 <code>demo threads</code>、Thread 專用清單命令或新的可觀測 TID 列表；目前診斷保留 Process row 與代表 TID。這些選擇不改動 Spec 的 syscall/stack ABI 與生命週期契約。</p><h2 id="驗證狀態" tabindex="-1">驗證狀態 <a class="header-anchor" href="#驗證狀態" aria-label="Permalink to &quot;驗證狀態&quot;">​</a></h2><p>僅執行核心/使用者映像編譯與連結：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MSYSTEM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;UCRT64&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .\\build\\portable\\msys64\\usr\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bash.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">noprofile </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">norc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;export PATH=/ucrt64/bin:/usr/bin:/bin; make -j4 all build/kernel-disk.elf&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>結果通過，輸出記錄為 <code>build/thread-stage-b-build.log</code>。依要求未新增或執行測試、未跑 QEMU/GUI，未碰日常磁碟。所有多 Thread 排程、join race、swap、I/O close/reopen、kill/fault/DMA 與 fork/exec runtime 行為仍標為 <strong>NOT_RUN</strong>；編譯通過不代表驗收通過。</p>`,10)])])}const u=a(r,[["render",l]]);export{k as __pageData,u as default};
